/**
 * awesome-opencode registry — the upstream reader.
 *
 * The repo publishes its catalog as a machine-readable FLAT ARRAY: `dist/registry.json`, generated by
 * `scripts/export-json.js` from one YAML file per entry under `data/<category>/`. It is read through
 * the GitHub contents API with the raw media type, because `raw.githubusercontent.com` resets the
 * connection from this environment while `api.github.com` is the host the GitHub search adapter
 * already talks to.
 *
 * No cache lives here on purpose: browsing caches the answered list in `browse.ts` (one upstream read
 * serves every keystroke), while an install resolves ONE entry at a time and must not be answered from
 * a list fetched for a different purpose. The package-identity rules live in `catalog-npm.ts`, shared
 * with the other community catalog.
 */

import { describeFetchFailure, fetchFailureReason, fetchWithRetry, type FailureReason } from './net.js';

const REGISTRY_URL =
  'https://api.github.com/repos/awesome-opencode/awesome-opencode/contents/dist/registry.json';

/** One entry of `dist/registry.json`, narrowed to the fields this build reads. */
export interface AwesomeEntry {
  productId?: string;
  type?: string;
  displayName?: string;
  repoUrl?: string;
  tagline?: string;
  description?: string;
  tags?: string[];
  homepageUrl?: string;
  /** Free-form markdown install instructions; when present it may name the package verbatim. */
  installation?: string;
}

export type AwesomeRegistryResult =
  | { ok: true; entries: AwesomeEntry[] }
  | { ok: false; code: 'unavailable' | 'upstream'; reason: FailureReason; reasonParams?: Record<string, string>; message: string };

function githubHeaders(): Record<string, string> {
  const token = process.env.GITHUB_TOKEN?.trim();
  return {
    Accept: 'application/vnd.github.raw',
    'User-Agent': 'omnicellrouter-harness',
    ...(token ? { Authorization: `Bearer ${token}` } : {}),
  };
}

/** Read and decode the registry. The contents API may honor `raw` or answer a base64 envelope. */
export async function fetchAwesomeRegistry(fetchImpl: typeof fetch = fetch): Promise<AwesomeRegistryResult> {
  let res: Response;
  try {
    // Every failed answer is retried inside the shared policy (see `MARKET_RETRY`); a rate-limited
    // answer that outlasts the retries keeps its own `rateLimited` reason below.
    res = await fetchWithRetry(REGISTRY_URL, { headers: githubHeaders() }, undefined, { fetchImpl });
  } catch (e) {
    return { ok: false, code: 'upstream', reason: fetchFailureReason(e), message: describeFetchFailure('GitHub API', e) };
  }
  if (res.status === 403 || res.status === 429) {
    return {
      ok: false,
      code: 'unavailable',
      reason: 'rateLimited',
      message: 'GitHub API rate limit reached — set GITHUB_TOKEN to raise it',
    };
  }
  if (!res.ok) {
    return {
      ok: false,
      code: 'upstream',
      reason: 'http',
      reasonParams: { status: String(res.status) },
      message: `GitHub returned HTTP ${res.status}`,
    };
  }

  const text = await res.text();
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    return { ok: false, code: 'upstream', reason: 'badPayload', message: 'registry.json was not JSON' };
  }
  // A proxy or an ignored media type can answer the contents envelope instead of the file bytes.
  const envelope = parsed as { content?: unknown; encoding?: unknown };
  if (!Array.isArray(parsed) && typeof envelope.content === 'string' && envelope.encoding === 'base64') {
    try {
      parsed = JSON.parse(Buffer.from(envelope.content, 'base64').toString('utf8'));
    } catch {
      return { ok: false, code: 'upstream', reason: 'badPayload', message: 'registry.json envelope did not decode to JSON' };
    }
  }
  if (!Array.isArray(parsed)) {
    return { ok: false, code: 'upstream', reason: 'badPayload', message: 'registry.json is not a flat array' };
  }
  return { ok: true, entries: parsed as AwesomeEntry[] };
}
